package com.focusflow.api.repository; import com.focusflow.api.entity.Task; import org.springframework.data.jpa.repository.*; import java.time.LocalDate; import java.util.*; public interface TaskRepository extends JpaRepository<Task,String>{List<Task> findByUserIdOrderByDueDateAscDueTimeAsc(String userId); Optional<Task> findByIdAndUserId(String id,String userId); List<Task> findByUserIdAndDueDate(String u,LocalDate d); List<Task> findByUserIdAndDueDateAfter(String u,LocalDate d); List<Task> findByUserIdAndDueDateBeforeAndStatusNot(String u,LocalDate d,Task.Status s); List<Task> findByUserIdAndStatus(String u,Task.Status s); @Modifying void deleteByUserId(String userId);}
